-- Add 'Vascular' to quickfireQuestions.category enum
ALTER TABLE `quickfireQuestions` MODIFY COLUMN `category` ENUM(
  'Abdominal','Pelvic/Gyn','OB 1st Trimester','OB 2nd/3rd Trimester','Fetal Echo',
  'Venous','Arterial','Vascular','Abdominal Vascular','Extracranial Carotid',
  'Intracranial Duplex/TCD','POCUS','Physics','Thyroid','Scrotum','Breast','MSK'
) NOT NULL DEFAULT 'Abdominal';

-- Add 'Vascular' to quickfireChallenges.category enum
ALTER TABLE `quickfireChallenges` MODIFY COLUMN `category` ENUM(
  'Abdominal','Pelvic/Gyn','OB 1st Trimester','OB 2nd/3rd Trimester','Fetal Echo',
  'Venous','Arterial','Vascular','Abdominal Vascular','Extracranial Carotid',
  'Intracranial Duplex/TCD','POCUS','Physics','Thyroid','Scrotum','Breast','MSK'
) NOT NULL DEFAULT 'Abdominal';

-- Migrate all Venous challenges to Vascular
UPDATE `quickfireChallenges` SET `category` = 'Vascular' WHERE `category` = 'Venous';

-- Verify
SELECT category, COUNT(*) as cnt FROM quickfireChallenges GROUP BY category ORDER BY cnt DESC;

